function go(to){location.hash=to}
function dashboard(){
  const rows=dashboardState.rows
  const liveCount=rows.filter(row=>row.publish_status==='live').length
  const configuredCount=rows.filter(row=>row.ga4_connection_status==='configured').length
  const syncedCount=rows.filter(row=>row.latest_sync_status==='succeeded').length
  const conversionAvg=rows.length?Math.round((rows.reduce((sum,row)=>sum+Number(row.conversion_rate_30d||0),0)/rows.length)*100)/100:0
  const topRows=[...rows].sort((a,b)=>Number(b.conversions_30d||0)-Number(a.conversions_30d||0)).slice(0,5)
  const issueRows=rows.filter(row=>row.ga4_connection_status!=='configured'||row.latest_sync_status==='failed'||row.publish_status!=='live').slice(0,5)
  return `<div class="heading-row"><div><div class="eyebrow">OVERVIEW</div><h1>LP管理ダッシュボード</h1><p class="page-sub">公開中LP、GA4接続、同期状態、直近30日の成果を管理者がまとめて確認できます。</p></div><div class="ga4-actions"><button class="secondary" data-action="dashboard-refresh">更新</button><button class="primary" data-action="new">＋ 新規LPを作成</button></div></div>${dashboardState.error?`<div class="ga4-empty">${escapeHtml(dashboardState.error)}</div>`:''}<div class="stat-grid"><div class="panel stat"><small>管理LP数</small><strong>${formatCount(rows.length)} <small>件</small></strong><span>登録済みLP</span></div><div class="panel stat"><small>公開中LP</small><strong>${formatCount(liveCount)} <small>件</small></strong><span>live flag が立っているLP</span></div><div class="panel stat"><small>GA4設定済み</small><strong>${formatCount(configuredCount)} <small>件</small></strong><span>Property ID と page path 設定済み</span></div><div class="panel stat"><small>平均CVR(30日)</small><strong>${conversionAvg.toFixed(2)} <small>%</small></strong><span>LP平均</span></div></div><div class="dashboard-grid"><section class="panel section-card"><h2>状態サマリ</h2><ul class="mini-list"><li><span>GA4同期成功</span><b>${formatCount(syncedCount)}件</b></li><li><span>GA4未設定・不足</span><b>${formatCount(rows.filter(row=>row.ga4_connection_status!=='configured').length)}件</b></li><li><span>公開未反映</span><b>${formatCount(rows.filter(row=>row.publish_status!=='live').length)}件</b></li><li><span>最新分析あり</span><b>${formatCount(rows.filter(row=>row.latest_analysis_result_id).length)}件</b></li></ul></section><section class="panel section-card"><h2>成果上位LP（直近30日）</h2>${topRows.length?`<ul class="mini-list">${topRows.map(row=>`<li><span>${escapeHtml(row.client_name)} / ${escapeHtml(row.lp_name)}</span><b>CV ${formatCount(row.conversions_30d)} / CVR ${Number(row.conversion_rate_30d||0).toFixed(2)}%</b></li>`).join('')}</ul>`:`<div class="ga4-empty">表示できる GA4 データがまだありません。</div>`}</section><section class="panel section-card"><h2>優先確認LP</h2>${issueRows.length?`<ul class="mini-list">${issueRows.map(row=>`<li><span>${escapeHtml(row.client_name)} / ${escapeHtml(row.lp_name)}</span><b>${row.ga4_connection_status!=='configured'?'GA4設定確認':row.latest_sync_status==='failed'?'同期失敗':'公開状態確認'}</b></li>`).join('')}</ul>`:`<div class="ga4-empty">優先確認項目はありません。</div>`}</section></div><section class="panel table-panel"><div class="heading-row"><div><h2>LP運用状況</h2><p class="page-sub">直近30日集計、同期状況、公開状態をLP単位で確認します。</p></div></div>${dashboardState.loading&&!rows.length?`<div class="ga4-empty">ダッシュボードデータを読み込み中です。</div>`:''}${!rows.length&&!dashboardState.loading?`<div class="ga4-empty">対象データがありません。</div>`:`<table><thead><tr><th>クライアント / LP</th><th>公開状態</th><th>GA4</th><th>直近30日</th><th>最新同期 / 分析</th></tr></thead><tbody>${rows.map(row=>`<tr><td><div class="lp-name">${escapeHtml(row.lp_name)}</div><div class="client">${escapeHtml(row.client_name)}</div><div class="ga4-meta"><span>folder: <b>${escapeHtml(row.folder_path)}</b></span><span>URL: <b>${escapeHtml(row.public_url)}</b></span></div></td><td><div class="ga4-field-list">${statusBadge(row.publish_status==='live'?'公開中':'未公開',dashboardTone(row.publish_status))}<span>version <b>${escapeHtml(row.live_version_label||'未設定')}</b></span><span>commit <b>${escapeHtml(row.live_commit_sha||'未設定')}</b></span><span>公開日時 <b>${escapeHtml(formatDisplayDate(row.live_published_at))}</b></span></div></td><td><div class="ga4-field-list">${statusBadge(row.ga4_connection_status==='configured'?'設定済み':row.ga4_connection_status==='partial'?'一部不足':'未設定',dashboardTone(row.ga4_connection_status))}<span>property <b>${escapeHtml(row.ga4_property_id||'未設定')}</b></span><span>path <b>${escapeHtml(row.ga4_page_path||'未設定')}</b></span></div></td><td><div class="ga4-field-list"><span>sessions <b>${formatCount(row.sessions_30d)}</b></span><span>users <b>${formatCount(row.total_users_30d)}</b></span><span>pageViews <b>${formatCount(row.page_views_30d)}</b></span><span>CV <b>${formatCount(row.conversions_30d)}</b></span><span>CVR <b>${row.conversion_rate_30d===null?'--':`${Number(row.conversion_rate_30d).toFixed(2)}%`}</b></span></div></td><td><div class="ga4-field-list">${statusBadge(row.latest_sync_status||'未実行',dashboardTone(row.latest_sync_status||'failed'))}<span>最終取得 <b>${escapeHtml(formatDisplayDate(row.latest_sync_finished_at))}</b></span><span>最終分析 <b>${escapeHtml(formatDisplayDate(row.latest_analysis_created_at))}</b></span>${row.latest_sync_error_message?`<span>同期エラー <b>${escapeHtml(row.latest_sync_error_message)}</b></span>`:''}</div></td></tr>`).join('')}</tbody></table>`}</section>`
}
function apiLogsAdmin(){
  const auth=currentAuth()
  if(!auth.isAdmin){
    return `<div class="ga4-empty">このページは管理者のみ表示できます。</div>`
  }
  const rows=apiLogState.rows
  const errorCount=rows.filter(row=>row.level==='error').length
  const warnCount=rows.filter(row=>row.level==='warn').length
  const latest=rows[0]?.created_at||null
  return `<div class="ga4-check-grid"><div class="heading-row"><div><div class="eyebrow">API LOGS</div><h1>APIログ確認</h1><p class="page-sub">Edge Functions の受信、検証、ジョブ投入、失敗内容を時系列で確認できます。</p></div><button class="secondary" data-action="api-log-refresh">一覧を更新</button></div>${apiLogState.error?`<div class="ga4-empty">${escapeHtml(apiLogState.error)}</div>`:''}<div class="ga4-summary-grid"><section class="ga4-summary-card"><small>表示件数</small><strong>${rows.length}</strong><span>直近120件</span></section><section class="ga4-summary-card"><small>Error</small><strong>${errorCount}</strong><span>level=error</span></section><section class="ga4-summary-card"><small>Warn</small><strong>${warnCount}</strong><span>level=warn</span></section><section class="ga4-summary-card"><small>最新ログ</small><strong>${latest?formatDisplayDate(latest):'未取得'}</strong><span>created_at</span></section></div>${apiLogState.loading&&!rows.length?`<div class="ga4-empty">APIログを読み込み中です。</div>`:''}${!rows.length&&!apiLogState.loading?`<div class="ga4-empty">まだ API ログはありません。</div>`:`<section class="panel table-panel"><table><thead><tr><th>時刻</th><th>Function / Stage</th><th>対象</th><th>内容</th><th>結果</th></tr></thead><tbody>${rows.map(row=>`<tr><td><div class="ga4-field-list"><span>${escapeHtml(formatDisplayDate(row.created_at))}</span><span>request <b>${escapeHtml(row.request_id)}</b></span></div></td><td><div class="ga4-field-list"><span>${statusBadge(row.level,row.level==='error'?'error':row.level==='warn'?'warn':'ok')}</span><span><b>${escapeHtml(row.function_name)}</b></span><span>${escapeHtml(row.stage)}</span></div></td><td><div class="ga4-field-list"><span>client <b>${escapeHtml(row.client_name||'--')}</b></span><span>lp <b>${escapeHtml(row.lp_name||'--')}</b></span><span>actor <b>${escapeHtml(row.actor_email||'--')}</b></span></div></td><td><div class="ga4-field-list"><span>${escapeHtml(row.message)}</span>${row.metadata&&Object.keys(row.metadata).length?`<span><b>${escapeHtml(JSON.stringify(row.metadata))}</b></span>`:''}</div></td><td><div class="ga4-field-list"><span>HTTP <b>${escapeHtml(row.http_method||'--')}</b></span><span>Status <b>${escapeHtml(row.status_code||'--')}</b></span><span>Duration <b>${escapeHtml(row.duration_ms||'--')}</b></span></div></td></tr>`).join('')}</tbody></table></section>`}</div>`
}
function detailContext(active){return `<div class="back" onclick="go('lps')">‹ LP一覧に戻る</div><section class="panel detail-hero"><div class="detail-heading"><div><div class="eyebrow">LP DETAIL / LP-2025-001</div><h1>${selected.name}</h1><p class="page-sub">${selected.client}　｜　公開URL： <b>https://example.com/lp/eyebee</b></p></div><div><button class="secondary" data-action="rollback">↶ ロールバック</button> <button class="primary" data-action="publish">公開する</button></div></div><div class="detail-meta"><div>ヘルススコア<b><span class="score ${scoreClass(selected.score)}">${selected.score}</span></b></div><div>現在のフェーズ<b>${selected.phase}</b></div><div>最新バージョン<b>v2.4（レビュー中）</b></div><div>次のアクション<b>CTA改善案を確認</b></div></div></section><div class="tabs"><button class="${active==='detail'?'active':''}" onclick="go('detail')">概要</button><button class="${active==='analysis'?'active':''}" onclick="go('analysis')">分析</button><button class="${active==='proposals'?'active':''}" onclick="go('proposals')">改善提案</button><button class="${active==='versions'?'active':''}" onclick="go('versions')">バージョン</button><button>公開履歴</button></div>`}
function detail(){return detailContext('detail')+`<div class="detail-grid"><section class="panel preview"><div class="phone"><small>EYEBEE</small><h3>印象が変わる<br>目元に、私らしさを。</h3><p>目元の悩みに寄り添う<br>自然なデザインをご提案。</p><div class="line-btn">LINEで予約する</div></div></section><section class="panel detail-info"><h2>AIによる作成意図・レビュー観点</h2><p>働く30代女性の「目元の印象を変えたい」という悩みに焦点を当て、安心感と予約への期待感を両立する構成で設計しています。</p><hr><h2>確認してほしいポイント</h2><ul class="checklist"><li>FVの訴求がターゲットの悩みに刺さっているか</li><li>予約CTAがファーストビューで明確か</li><li>実績・口コミが十分な安心材料になっているか</li></ul><div class="actions"><button class="secondary" data-action="rollback">差し戻す</button><button class="secondary" data-action="approve">条件付き承認</button><button class="primary" data-action="approve">承認する</button></div></section></div>`}
function analysis(){return `<div class="heading-row"><div><div class="eyebrow">PERFORMANCE</div><h1>LP分析</h1><p class="page-sub">eyebee 岡山黒石店｜まつげパーマ LP のパフォーマンス</p></div><button class="secondary">期間：直近30日 ▾</button></div><div class="stat-grid"><div class="panel stat"><small>セッション</small><strong>12,486</strong><span>+18.2%</span></div><div class="panel stat"><small>CV数</small><strong>599</strong><span>+22.0%</span></div><div class="panel stat"><small>CVR</small><strong>4.80%</strong><span>+0.42pt</span></div><div class="panel stat"><small>直帰率</small><strong>38.4%</strong><span>−4.1pt</span></div></div><div class="dashboard-grid"><section class="panel section-card"><h2>CVR 推移</h2><div class="chart"><svg viewBox="0 0 400 210" preserveAspectRatio="none"><path d="M0 160 C45 90,78 180,120 115 S170 142,211 98 S260 145,300 70 S350 105,400 40" fill="none" stroke="#1768f2" stroke-width="4"/></svg></div></section><section class="panel section-card"><h2>流入チャネル</h2><ul class="mini-list"><li><span>Google / Organic</span><b>46.2%</b></li><li><span>Instagram</span><b>28.7%</b></li><li><span>Google広告</span><b>17.4%</b></li><li><span>Direct</span><b>7.7%</b></li></ul></section><section class="panel section-card"><h2>AIインサイト</h2><p>FV到達後の離脱が前週比で改善。予約ボタンのクリック率は高い一方、料金セクションでの離脱が残っています。</p><button class="primary" onclick="go('proposals')">改善提案を見る</button></section></div>`}
function proposals(){return `<div class="heading-row"><div><div class="eyebrow">AI OPTIMIZATION</div><h1>改善提案</h1><p class="page-sub">データとAI分析に基づく、優先度順の改善アクションです。</p></div><button class="secondary">eyebee 岡山黒石店 ▾</button></div><div class="proposal-grid">${[['高','ファーストビューの訴求を明確化','現在のFVは画像の印象が強く、ベネフィットが伝わるまでに時間がかかっています。ファーストビューに悩み直結のコピーを追加します。','予測CVR +0.6pt'],['中','料金セクションの比較を簡潔に','料金表への到達後に離脱が見られます。プラン数を絞り、選びやすい比較表示へ変更します。','予測CVR +0.3pt'],['中','予約CTAを追従表示へ','スマートフォンでのスクロール中にも予約導線を維持し、予約率を高めます。','予測CVR +0.2pt'],['低','口コミカードの視認性を改善','評価・ビフォーアフターの実績を、より短時間で読めるレイアウトにします。','安心感向上']].map((p,i)=>`<section class="panel proposal"><div class="tag">優先度：${p[0]}</div><h3>${p[1]}</h3><p>${p[2]}</p><div class="impact"><span class="tag">${p[3]}</span><button class="primary" data-action="approve">提案を承認</button></div></section>`).join('')}</div>`}
function versions(){return `<div class="heading-row"><div><div class="eyebrow">VERSION CONTROL</div><h1>バージョン管理</h1><p class="page-sub">eyebee 岡山黒石店｜まつげパーマ LP</p></div><button class="primary" data-action="new">＋ 新バージョンを作成</button></div><div class="version-grid">${[['v2.4','最新｜レビュー中','CTAの文言とFVコピーを改善','今日 10:15'],['v2.3','公開中','口コミセクションの見出しを変更','2025/05/18 16:22'],['v2.2','公開履歴','料金プランの表示順を更新','2025/05/08 11:44'],['v2.1','公開履歴','初回公開バージョン','2025/04/26 13:20']].map((v,i)=>`<section class="panel version ${i===0?'current':''}"><div class="version-number">${v[0]}</div><span class="status ${i===0?'review':'live'}">${v[1]}</span><h3>${v[2]}</h3><p class="page-sub">更新：${v[3]}　山田 太郎</p><div class="actions"><button class="secondary">プレビュー</button>${i>0?'<button class="secondary" data-action="rollback">この版に戻す</button>':'<button class="primary" data-action="publish">公開する</button>'}</div></section>`).join('')}</div>`}
function alerts(){return `<div class="heading-row"><div><div class="eyebrow">MONITORING</div><h1>アラート</h1><p class="page-sub">LPの成果・公開状態・計測に関する異常を監視しています。</p></div><button class="secondary">期間：今週 ▾</button></div><section class="panel">${[['緊急','LPの表示エラーが発生しています','eyebee 岡山北店｜/lp/eyebee','LPの表示を確認し修正する'],['緊急','フォーム送信エラーを検知しました','Resole 田町店｜/contact','フォーム設定・連携を確認する'],['注意','計測タグが停止しています','chacha 給井町店｜GTM-XXXX','タグ設置状況・設定を確認する'],['情報','CVRが先週比で上昇しました','Bianca 銀座店｜+0.8pt','分析レポートを確認する']].map(x=>`<div class="alert-row"><span class="status ${x[0]==='緊急'?'draft':'review'}">${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div><b>${x[3]} →</b><button class="secondary" data-action="other">詳細を確認</button></div>`).join('')}</section>`}
function render(){const views={dashboard,lps:list,detail,analysis,proposals,versions,alerts}; page=location.hash.replace('#','')||'lps'; const detailTabs=['analysis','proposals','versions']; pageEl.innerHTML=(detailTabs.includes(page)?detailContext(page):'')+(views[page]||list)();crumb.innerHTML=`LP管理 <span>/</span> ${({dashboard:'ダッシュボード',lps:'LP一覧',detail:'LP詳細',analysis:'LP詳細 / 分析',proposals:'LP詳細 / 改善提案',versions:'LP詳細 / バージョン管理',alerts:'アラート'})[page]||'LP一覧'}`;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));buttons()}
window.addEventListener('hashchange',render);document.querySelector('#search').addEventListener('input',e=>{if(page!=='lps')return;document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.includes(e.target.value)?'':'none')});render();

