let viewerRole='internal';
const viewerMode=document.querySelector('#viewerMode');
const lpPicker=document.querySelector('#lpPicker');
const ownClient='株式会社eyebee';
function accessibleLps(){return viewerRole==='client'?lps.filter(lp=>lp.client===ownClient):lps}
function syncLpPicker(){
  const choices=accessibleLps();
  if(!choices.includes(selected)) selected=choices[0];
  lpPicker.innerHTML=choices.map(lp=>`<option value="${lps.indexOf(lp)}">${lp.name}</option>`).join('');
  lpPicker.value=String(lps.indexOf(selected));
  const adminListLink=document.querySelector('[data-page="lps"]');
  adminListLink.style.display=viewerRole==='client'?'none':'';
  const productionLink=document.querySelector('[data-page="production"]');
  if(productionLink) productionLink.style.display=viewerRole==='client'?'none':'';
}
function history(){return `<div class="heading-row"><div><div class="eyebrow">PUBLISH HISTORY</div><h1>公開履歴</h1><p class="page-sub">${selected.name} の公開・ロールバック履歴</p></div><button class="primary" data-action="publish">このバージョンを公開</button></div><section class="panel section-card"><ul class="mini-list"><li><span><b>v2.3 を公開</b><br>CTAと料金セクションを更新</span><b>2025/05/18 16:22</b></li><li><span><b>v2.2 を公開</b><br>料金プランの表示順を更新</span><b>2025/05/08 11:44</b></li><li><span><b>v2.1 を公開</b><br>LP初回公開</span><b>2025/04/26 13:20</b></li></ul></section>`}
function setFunnelChannel(channel){funnelChannel=channel;renderWithDetailMenu()}
function funnel(){const data={all:{label:'すべて',spend:'¥182,400',access:'12,486',cv:'599',detail:'広告流入 7,220 ／ 自然流入 5,266'},meta:{label:'Meta広告',spend:'¥82,400',access:'5,480',cv:'238',detail:'Instagram・Facebook経由'},google:{label:'Google広告',spend:'¥100,000',access:'3,120',cv:'191',detail:'検索広告経由'},instagram:{label:'Instagram',spend:'—',access:'1,840',cv:'72',detail:'オーガニック投稿経由'}}[funnelChannel];return `<section class="panel funnel-panel"><div class="funnel-title"><div><h2>マーケティングファネル</h2><div class="funnel-filter"><span>流入経路</span>${[['all','すべて'],['meta','Meta広告'],['google','Google広告'],['instagram','Instagram']].map(([key,label])=>`<button class="${funnelChannel===key?'active':''}" onclick="setFunnelChannel('${key}')">${label}</button>`).join('')}</div></div><span class="funnel-note">広告媒体連携は後フェーズで実装予定</span></div><div class="funnel-flow"><div class="funnel-stage"><small>広告 / 流入経路</small><strong>${data.label}</strong><div class="client">${data.spend}</div></div><div class="funnel-arrow">→</div><div class="funnel-stage"><small>アクセス数</small><strong>${data.access} <small>sessions</small></strong><div class="client">${data.detail}</div></div><div class="funnel-arrow">→</div><div class="funnel-stage"><small>CV数</small><strong>${data.cv} <small>CV</small></strong><div class="client">CVR ${(Number(data.cv.replace(',',''))/Number(data.access.replace(',',''))*100).toFixed(2)}%</div></div></div></section>`}
reportMonth='2025年5月';
reportMonths=['2025年5月','2025年4月','2025年3月','2025年2月','2025年1月','2024年12月'];
function setReportMonth(month){reportMonth=month;renderWithDetailMenu()}
function monthButtons(){return `<div class="month-bar"><span>表示期間</span>${reportMonths.map(month=>`<button class="${reportMonth===month?'active':''}" onclick="setReportMonth('${month}')">${month.replace('2025年','').replace('2024年','')}</button>`).join('')}</div>`}
function lpMetrics(index){const offset=Math.max(0,reportMonths.indexOf(reportMonth));const traffic=3420+(index*510)-(offset*165);const cv=Math.max(8,Math.round(traffic*(.046-index*.003+offset*.001)));const cvr=(cv/traffic*100).toFixed(2);const trafficChange=offset===0?'+12.4%':`${offset%2===0?'+':'-'}${(3.2+offset*1.1).toFixed(1)}%`;const cvChange=offset===0?'+8.6%':`${offset%2===0?'+':'-'}${(2.4+offset*.9).toFixed(1)}%`;const cvrChange=offset===0?'+0.18pt':`${offset%2===0?'+':'-'}0.${10+offset*3}pt`;return {traffic,cv,cvr,trafficChange,cvChange,cvrChange}}
function metricCell(value,change){return `<b>${value}</b><small class="metric-change ${change.startsWith('-')?'down':''}">前月比 ${change}</small>`}
function lpTable(items,kind){return `<section class="panel lp-category-table"><div class="lp-category-title"><div><span>${kind}</span><h2>${kind}LP一覧</h2></div><b>${items.length} 件</b></div><div class="table-panel"><table><thead><tr><th>LP名 / 訴求</th><th>健全度</th><th>ステータス</th><th>流入数</th><th>CV数</th><th>CVR</th><th>最終更新</th><th></th></tr></thead><tbody>${items.map((lp,index)=>{const metrics=lpMetrics(index+(kind==='求人'?3:0));return `<tr><td><div class="lp-name">${lp.name.split('｜')[1]||lp.name}</div><div class="client">${kind==='求人'?'アイリスト・スタッフ採用':'サービス訴求LP'}</div></td><td><span class="score ${scoreClass(lp.score)}">${lp.score}</span></td><td><span class="status ${statusClass(lp.state||'レビュー中')}">${lp.state||'公開準備'}</span></td><td>${metricCell(metrics.traffic.toLocaleString(),metrics.trafficChange)}</td><td>${metricCell(metrics.cv,metrics.cvChange)}</td><td>${metricCell(metrics.cvr+'%',metrics.cvrChange)}</td><td>${lp.update}</td><td><button class="secondary" data-action="detail" data-name="${lp.dataName||lp.name}">詳細</button></td></tr>`}).join('')}</tbody></table></div></section>`}
function lpVariants(){const acquisition=lps.filter(lp=>lp.client===selected.client&&!lp.name.includes('求人'));const recruit=lps.filter(lp=>lp.client===selected.client&&lp.name.includes('求人'));const recruitItems=recruit.length?recruit:[{name:'求人LP｜アイリスト採用',score:74,state:'レビュー中',phase:'公開準備',owner:'山田',cv:'応募 18件',update:'5/21 13:20',dataName:selected.name}];return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">LP VARIATIONS</div><h1>LP一覧</h1><p class="page-sub">集客用LPと求人用LPを分けて確認できます。</p></div><span class="tag">${acquisition.length+recruitItems.length} LP</span></div>${monthButtons()}${lpTable(acquisition,'集客')}${lpTable(recruitItems,'求人')}`}
function clientFunnel(title,media,access,cv,color){return `<section class="panel overview-funnel"><div><span class="funnel-kind" style="background:${color}">${title}</span><h2>${title}のマーケティングファネル</h2></div><div class="overview-funnel-flow"><div><small>${media}</small><b>広告配信</b></div><i>→</i><div><small>アクセス数</small><b>${access}</b></div><i>→</i><div><small>CV数</small><b>${cv}</b></div></div></section>`}
function clientHome(){const clientLps=lps.filter(lp=>lp.client===selected.client);const acquisition=clientLps.filter(lp=>!lp.name.includes('求人'));const recruit=clientLps.filter(lp=>lp.name.includes('求人'));const recruitItems=recruit.length?recruit:[{name:'求人LP｜アイリスト採用',score:74,phase:'公開準備',cv:'応募 18件'}];return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">CLIENT OVERVIEW</div><h1>${selected.client}</h1><p class="page-sub">集客・求人それぞれのLP、広告、成果を確認します。</p></div><button class="secondary" onclick="go('lps')">管理者画面に戻る</button></div><div class="ad-summary-grid"><section class="panel ad-summary"><span>META広告</span><b>¥82,400</b><small>広告費　/　クリック 3,824</small><button onclick="go('meta-ads')">詳細を見る →</button></section><section class="panel ad-summary"><span>Google広告</span><b>¥100,000</b><small>広告費　/　クリック 2,120</small><button onclick="go('google-ads')">詳細を見る →</button></section><section class="panel ad-summary"><span>広告全体CV数</span><b>599</b><small>CVR 4.80%</small><button onclick="go('detail')">LP詳細を見る →</button></section></div>${clientFunnel('集客全体','META広告・Google広告','12,486','599','#1768f2')}${clientFunnel('求人全体','求人媒体・Google広告','3,820','18','#7a54e8')}<section class="panel section-card"><h2>集客LP一覧</h2><div class="client-lp-grid">${acquisition.map(lp=>`<button class="client-lp-card" data-action="detail" data-name="${lp.name}"><span class="score ${scoreClass(lp.score)}">${lp.score}</span><b>${lp.name.split('｜')[1]}</b><small>フェーズ：${lp.phase}　/　CVR ${lp.cv}</small><span>LP詳細を開く →</span></button>`).join('')}</div></section><section class="panel section-card recruit-section"><h2>求人LP一覧</h2><div class="client-lp-grid">${recruitItems.map(lp=>`<button class="client-lp-card" data-action="detail" data-name="${lp.name}"><span class="score ${scoreClass(lp.score)}">${lp.score}</span><b>${lp.name.split('｜')[1]}</b><small>フェーズ：${lp.phase}　/　${lp.cv}</small><span>LP詳細を開く →</span></button>`).join('')}</div></section>`}
let hqEnabled=false;
const stores=[{name:'岡山黒石店',lps:4,meta:'¥82,400',google:'¥100,000',cvr:'4.80%'},{name:'岡山駅西口店',lps:3,meta:'¥64,000',google:'¥76,000',cvr:'3.92%'},{name:'倉敷駅前店',lps:2,meta:'¥42,000',google:'¥51,000',cvr:'3.48%'}];
function hq(){return `<div class="heading-row"><div><div class="eyebrow">HEADQUARTERS</div><h1>本部管理</h1><p class="page-sub">全店舗のLP・広告・成果を横断して管理します。</p></div><button class="primary" data-action="new">＋ 店舗を追加</button></div><div class="stat-grid"><div class="panel stat"><small>管理店舗</small><strong>${stores.length} <small>店舗</small></strong><span>全店表示</span></div><div class="panel stat"><small>全店舗LP数</small><strong>9 <small>件</small></strong><span>集客・求人LPを含む</span></div><div class="panel stat"><small>広告費合計</small><strong>¥415,400</strong><span>今月</span></div><div class="panel stat"><small>全店平均CVR</small><strong>4.12%</strong><span>前月比 +0.2pt</span></div></div><section class="panel hq-table"><div class="hq-head"><span>店舗</span><span>LP数</span><span>META広告</span><span>Google広告</span><span>CVR</span><span></span></div>${stores.map(store=>`<div class="hq-row"><b>${store.name}</b><span>${store.lps} 件</span><span>${store.meta}</span><span>${store.google}</span><b>${store.cvr}</b><button class="secondary" data-action="store">店舗分析を見る</button></div>`).join('')}</section>`}
function settings(){return `<div class="heading-row"><div><div class="eyebrow">SETTINGS</div><h1>設定</h1><p class="page-sub">組織運用にあわせて機能を有効化します。</p></div></div><section class="panel setting-card"><div><h2>本部機能</h2><p>複数店舗のLP・広告・分析を、本部で横断管理できるようにします。</p></div><button class="${hqEnabled?'primary':'secondary'}" data-action="toggle-hq">${hqEnabled?'オン（有効）':'オフ（有効にする）'}</button></section><p class="page-sub">有効にすると、管理者画面に「本部管理」が表示されます。店舗追加と店舗別分析は後フェーズで実装します。</p>`}
function adChannel(channel,spend,clicks,cvr){return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">${channel.toUpperCase()} ADS</div><h1>${channel}広告</h1><p class="page-sub">${selected.name} に紐づく広告配信状況です。</p></div><span class="tag">広告連携は後フェーズ</span></div><div class="stat-grid"><div class="panel stat"><small>広告費</small><strong>${spend}</strong><span>表示用データ</span></div><div class="panel stat"><small>クリック数</small><strong>${clicks}</strong><span>表示用データ</span></div><div class="panel stat"><small>CV数</small><strong>128</strong><span>表示用データ</span></div><div class="panel stat"><small>CVR</small><strong>${cvr}</strong><span>表示用データ</span></div></div><section class="panel section-card"><h2>キャンペーン一覧</h2><ul class="mini-list"><li><span>キャンペーン：${selected.name.split('｜')[1]} 集客</span><b>配信準備中</b></li><li><span>計測・配信データの連携</span><b>後フェーズで実装</b></li></ul></section>`}
function metaAds(){return adChannel('META', '¥82,400', '3,824', '3.35%')}
function googleAds(){return adChannel('Google', '¥100,000', '2,120', '4.12%')}
