function applyFocInstructions(){const inputs=document.querySelectorAll('.foc-current-item textarea');const texts=['30代女性が共感しやすい、清潔感のある目元のクローズアップに変更。疲れて見える悩みから自然で上品な印象へ変化する期待感を表現し、初回価格が読みやすい余白を残す。','初回限定5,500円を最も大きく表示。通常価格との差額と「24時間Web予約OK」を添え、特典の期限と予約の簡単さが一目で伝わるデザインにする。','CTA文言を「LINEで空き状況を確認する」に変更。補足に「24時間受付・1分で予約完了」を置き、緑を基調に安心感と押しやすさを持たせる。'];inputs.forEach((input,index)=>input.value=texts[index]||input.value)}
function openVersionPreview(version){const data={v2_4:{status:'レビュー中',title:'印象が変わる目元に、ヨサヨナ',sub:'CTA文言とFVコピーを改善',price:'初回 5,500円',date:'2025/05/20 10:15'},v2_3:{status:'公開中',title:'疲れて見える目元に、ヨサヨナ',sub:'口コミセクションの見出しを変更',price:'初回 5,900円',date:'2025/05/18 16:22'},v2_2:{status:'公開履歴',title:'まつげパーマで理想の目元へ',sub:'料金プランの表示順を変更',price:'初回 5,900円',date:'2025/05/08 11:44'},v2_1:{status:'公開履歴',title:'自然な目元を叶えるサロン',sub:'初回公開バージョン',price:'初回 6,200円',date:'2025/04/26 13:20'}}[version.replace('.','_')];const modal=document.createElement('div');modal.className='version-modal';modal.innerHTML=`<div class="version-modal-backdrop" onclick="closeVersionPreview()"></div><section class="version-modal-card"><button class="version-modal-close" onclick="closeVersionPreview()">×</button><header><span>${data.status}</span><h3>${version} ｜ ${selected.name}</h3><p>${data.sub}<br>更新・公開日時：${data.date}</p></header><div class="version-modal-preview"><div class="version-modal-phone"><em>EYEBEE</em><div class="version-modal-photo"></div><h4>${data.title}</h4><p>自信で輝く印象へ</p><b>${data.price}</b><button>LINEで予約する</button></div></div><footer><button class="secondary" onclick="closeVersionPreview()">閉じる</button>${version!=='v2.4'?`<button class="primary" onclick="closeVersionPreview();notice('ロールバックを予約しました。現在のバージョンは保持されています。')">このバージョンへロールバック</button>`:''}</footer></section>`;document.body.appendChild(modal)}
function closeVersionPreview(){document.querySelector('.version-modal')?.remove()}
function openGtmSettings(){const modal=document.createElement('div');modal.className='gtm-modal';modal.innerHTML=`<div class="gtm-backdrop" onclick="closeGtmSettings()"></div><section class="gtm-modal-card"><button class="gtm-close" onclick="closeGtmSettings()">×</button><header><span>共通設定</span><h3>Google Tag Manager（GTM）設定</h3><p>GTMコンテナIDを保存すると、このクライアントの集客LP・求人LPへ共通タグを設置できる状態になります。</p></header><div class="gtm-body"><label>GTMコンテナID<input class="gtm-input" value="${gtmContainerId}" placeholder="GTM-XXXXXXX"></label><small>例：GTM-ABC1234</small><div class="gtm-status"><b>タグ設置状態</b><span>保存後、公開済みLPと今後作成するLPに共通タグを自動設置</span></div><p class="gtm-note">※ 現在はフロントモックです。実装フェーズではGTMの埋め込みコードを各LPのheadへ配置します。</p></div><footer><button class="secondary" onclick="closeGtmSettings()">キャンセル</button><button class="primary" onclick="saveGtmSettings()">GTM IDを保存する</button></footer></section>`;document.body.appendChild(modal)}
function closeGtmSettings(){document.querySelector('.gtm-modal')?.remove()}
