function openAppealDialog(){const modal=document.createElement('div');modal.className='appeal-modal';modal.innerHTML=`<div class="appeal-backdrop" onclick="closeAppealDialog()"></div><section class="appeal-modal-card"><button class="appeal-close" onclick="closeAppealDialog()">×</button><header><span>NEW APPEAL LP</span><h3>新しい訴求を試す</h3><p>既存LPをベースに複製し、Codexと壁打ちしながら異なる訴求のLPを作成します。</p></header><div class="appeal-modes"><div><b>マクロ：訴求を変えたLPを追加</b><small>ターゲット・悩み・価値提案を変え、新しいLPを検証</small></div><i>＋</i><div><b>ミクロ：LP詳細で継続改善</b><small>FOC・構成・ライティングを改善し、成果を高める</small></div></div><div class="appeal-body"><label>ベースにするLP<select class="appeal-base"><option>${selected.name}</option><option>eyebee 岡山黒石店｜眉毛スタイリング</option><option>eyebee 岡山黒石店｜初回キャンペーン</option></select></label><div class="appeal-chat"><div class="appeal-message ai"><b>Codex</b><p>現在のLPは「自然で上品な目元」を訴求しています。新しいLPでは、どのターゲット・悩み・価値を試したいですか？</p></div><label>検証したい訴求<textarea class="appeal-input" placeholder="例：仕事帰りの30代女性に向け、短時間で印象を変えられることを訴求したい">忙しい30代女性へ、短時間でも自然に垢抜ける目元を訴求したい</textarea></label><div class="appeal-message ai appeal-response"><b>Codexの訴求案</b><p>「仕事帰りの60分で、明日の印象を変える。」を主訴求にします。時間のなさを解決する価値を先に伝え、初回予約の手軽さへつなげる構成が有効です。</p></div><button class="secondary appeal-refine" onclick="refineAppeal()">この内容で訴求案を更新</button></div></div><footer><button class="secondary" onclick="closeAppealDialog()">キャンセル</button><button class="primary" onclick="createAppealLp()">この訴求でLPを複製して作成</button></footer></section>`;document.body.appendChild(modal)}
function closeAppealDialog(){document.querySelector('.appeal-modal')?.remove()}
function refineAppeal(){const input=document.querySelector('.appeal-input')?.value.trim()||'新しい訴求';const response=document.querySelector('.appeal-response p');if(response)response.textContent=`「${input}」を軸に、悩み → 得られる変化 → 予約の手軽さの順で伝える訴求案に更新しました。既存LPの成果データを引き継いで比較できます。`}
