function list(){const clientNames=[...new Set(lps.map(lp=>lp.client))];const clients=clientNames.map(name=>{const clientLps=lps.filter(lp=>lp.client===name);const average=Math.round(clientLps.reduce((sum,lp)=>sum+lp.score,0)/clientLps.length);return {name,lpCount:clientLps.length,average,live:clientLps.filter(lp=>lp.state==='公開中').length,owner:clientLps[0].owner,update:clientLps[0].update}});return `<div class="heading-row"><div><div class="eyebrow">ADMIN / CLIENT MANAGEMENT</div><h1>クライアント一覧</h1><p class="page-sub">クライアントのLP運用状況を確認し、個別クライアント画面を開きます。</p></div><button class="primary" data-action="new">＋ 新規クライアント</button></div><div class="toolbar"><button class="filter-btn active">すべて ${clients.length}</button><button class="filter-btn">要確認 2</button><button class="filter-btn">稼働中 ${clients.length}</button></div><section class="panel table-panel"><table><thead><tr><th>クライアント名</th><th>運用LP数</th><th>平均健全度</th><th>公開中LP</th><th>担当者</th><th>最終更新</th><th></th></tr></thead><tbody>${clients.map(client=>`<tr class="row-link"><td><button class="client-open client-name" data-action="open-client" data-client="${client.name}">${client.name}<span>個別クライアント画面を開く →</span></button></td><td><b>${client.lpCount} 件</b></td><td><span class="score ${scoreClass(client.average)}">${client.average}</span></td><td>${client.live} 件</td><td><div class="person"><span class="avatar">${client.owner.slice(0,1)}</span>${client.owner}</div></td><td>${client.update}</td><td>›</td></tr>`).join('')}</tbody></table><div class="pagination"><span>${clients.length} クライアントを表示</span></div></section>`}
function production(){return `<div class="heading-row"><div><div class="eyebrow">LP PRODUCTION</div><h1>新規LP制作一覧</h1><p class="page-sub">新規LPの制作進捗を管理する画面です。</p></div><span class="tag">機能実装は後フェーズ</span></div><div class="stat-grid"><div class="panel stat"><small>制作中</small><strong>${productionItems.length} <small>件</small></strong><span>今週公開予定 1件</span></div><div class="panel stat"><small>レビュー待ち</small><strong>1 <small>件</small></strong><span>設計済み</span></div><div class="panel stat"><small>素材待ち</small><strong>1 <small>件</small></strong><span>設計済み</span></div><div class="panel stat"><small>平均進捗</small><strong>${Math.round(productionItems.reduce((sum,item)=>sum+item.progress,0)/productionItems.length)}%</strong><span>表示用データ</span></div></div><section class="panel production-panel"><div class="production-head"><span>LP / クライアント</span><span>現在の工程</span><span>担当者</span><span>進捗</span><span>期限</span><span>次アクション</span></div>${productionItems.map(item=>`<div class="production-row"><div><b>${item.name}</b><small>${item.client}</small></div><div><span class="tag">${item.phase}</span></div><div>${item.owner}</div><div><b>${item.progress}%</b><div class="bar"><i style="width:${item.progress}%"></i></div></div><div>${item.due}</div><div>${item.next}</div></div>`).join('')}</section>`}
function initialProductionLegacy(){return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">INITIAL LP PRODUCTION</div><h1>初期LP制作</h1><p class="page-sub">ベースのLPテンプレートをもとに、ヒアリングからクライアント確認までを一元管理します。</p></div><button class="secondary" onclick="go('initial-settings')">ベースLPを設定</button></div><section class="panel template-source"><div><span>BASE TEMPLATE</span><h2>eyebee サロン集客LPテンプレート</h2><p>GitHub：github.com/eyebee/lp-website　/　フォルダ：/templates/salon-acquisition</p></div><div><b>ベースLP</b><small>このテンプレートを複製して制作します</small></div></section><section class="initial-workflow"><article class="done"><i>1</i><div><b>テンプレートを複製</b><small>ベースLPテンプレートをクライアント用に作成</small></div><span>完了</span></article><article class="active"><i>2</i><div><b>ヒアリングGPTsを提出</b><small>クライアントがGPTsで回答し、提出</small></div><span>提出待ち</span></article><article><i>3</i><div><b>担当者がLP制作</b><small>提出内容をもとにコピー・構成を作成</small></div><span>未着手</span></article><article><i>4</i><div><b>重要画像を個別生成</b><small>FV・オファー・CTAの画像を生成</small></div><span>未着手</span></article><article><i>5</i><div><b>クライアント確認</b><small>プレビューURLで確認・承認</small></div><span>未着手</span></article></section><div class="initial-work-grid"><section class="panel hearing-management"><header><div><span>CLIENT HEARING</span><h3>ヒアリングGPTsの管理</h3></div><button class="secondary" data-action="send-hearing-gpt">GPTsを案内</button></header><div class="hearing-state"><span>クライアント提出状況</span><b>未提出</b><small>依頼送信後、クライアントはGPTsの回答結果をここへ提出します。</small></div><div class="hearing-deliverable"><b>提出される内容</b><span>サービス内容 / ターゲット / 強み / 競合 / 画像素材 / CV目的</span></div><button class="primary" data-action="review-hearing">提出内容を確認してLP制作へ進む</button></section><section class="panel production-work"><span>INTERNAL PRODUCTION</span><h3>担当者のLP制作</h3><ul><li>ヒアリング内容から訴求・構成・コピーを反映</li><li>テンプレートのセクションをクライアント用に編集</li><li>GTM・CV設定を引き継ぎ</li></ul><div><b>担当：山田 太郎</b><small>着手条件：ヒアリングGPTs提出済み</small></div></section></div><section class="panel initial-assets"><header><div><span>FOCUSED IMAGE GENERATION</span><h3>重要3要素の画像生成</h3><p>LP全体とは別に、成果へ影響するFV・オファー・CTAを個別に生成します。</p></div><button class="primary" data-action="generate-initial-assets">画像を生成する</button></header><div><article><b>01</b><h4>ファーストビュー</h4><p>メインビジュアル・悩み訴求・初回価格</p><span>生成待ち</span></article><article><b>02</b><h4>オファー</h4><p>特典・価格・期限が伝わる画像</p><span>生成待ち</span></article><article><b>03</b><h4>CTA</h4><p>予約行動を促すボタン・補足画像</p><span>生成待ち</span></article></div></section><section class="panel initial-preview"><div><span>CLIENT PREVIEW</span><h3>クライアント確認用プレビュー</h3><p>制作完了後は、仮URLでLPを確認してもらい、承認後に公開します。</p><code>https://preview.example.com/eyebee/initial-lp</code></div><div><span>ステータス：制作前</span><button class="secondary" data-action="send-initial-preview">プレビューを送信</button></div></section>`}
function initialSettings(){return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">INITIAL SETUP</div><h1>初期設定</h1><p class="page-sub">最初のベースになるLPを登録し、初期LP制作フローの複製元として設定します。</p></div></div><section class="panel base-lp-settings"><header><div><span>BASE LP REGISTRATION</span><h2>ベースLPを登録</h2><p>GitHubリポジトリを登録し、対象LPまたはリポジトリ内フォルダを選択します。</p></div><span class="base-status">未保存の変更なし</span></header><div class="base-settings-grid"><label>GitHubリポジトリ<input value="https://github.com/eyebee/lp-website" placeholder="https://github.com/org/repository"></label><label>ブランチ<select><option>main</option><option>develop</option></select></label><label class="wide">LPの指定方法<div class="base-method"><label><input type="radio" name="base-method" checked> リポジトリ内からフォルダを選択</label><label><input type="radio" name="base-method"> LPのURLを指定</label></div></label><label class="wide">対象フォルダ<select><option>/apps/eyebee-kuroishi-lp</option><option>/apps/eyebee-recruit-lp</option><option>/archive/eyebee-old-lp</option></select><small>リポジトリの構成を読み取り、LPとして認識したフォルダから選択します。</small></label></div><section class="base-lp-detected"><b>検出したベースLP</b><div><span>LP</span><strong>eyebee 岡山黒石店｜まつげパーマ</strong><small>index.html / assets / GTM設定あり</small></div></section><footer><small>保存後、このLPを初期LP制作・訴求別LP複製のベースとして利用します。</small><button class="primary" data-action="save-base-lp">ベースLPを保存</button></footer></section>`}
function setInitialPhase(phase){initialPhase=phase;renderWithDetailMenu()}
function initialPhaseContentLegacy(){
  if(initialPhase===1)return `<section class="phase-panel"><header><span>PHASE 1</span><h2>テンプレートを複製</h2><p>ベースLPテンプレートのプレビューから、今回の制作に使うテンプレートを選択します。</p></header><div class="template-choice-grid"><article class="selected"><div class="template-mini"><b>EYEBEE</b><h3>自然で上品な<br>目元に</h3><button>LINEで予約</button></div><div><h3>サロン集客LPテンプレート</h3><p>サービス訴求・料金・口コミ・予約CTAを含む標準テンプレート</p><span>選択中</span></div></article><article><div class="template-mini recruit"><b>EYEBEE RECRUIT</b><h3>好きな仕事を<br>もっと自由に</h3><button>応募する</button></div><div><h3>求人LPテンプレート</h3><p>募集要項・働き方・スタッフ紹介を含む求人向けテンプレート</p><span>選択する</span></div></article></div><footer><small>選択したテンプレートは、初期設定のベースLPとして保存されます。</small><button class="primary" data-action="select-template">このテンプレートを複製</button></footer></section>`;
  if(initialPhase===2)return `<section class="phase-panel"><header><span>PHASE 2</span><h2>ヒアリングGPTsを案内・確認</h2><p>業種に合わせたヒアリングGPTsのURLと送信用フォーマットをクライアントへ送り、回答結果を提出してもらいます。</p></header><section class="hearing-url"><div><b>業種：美容室・アイラッシュサロン</b><code>https://chatgpt.com/g/g-hearing-beauty-lp</code><small>ヒアリングGPTs URL</small></div><button class="secondary" data-action="copy-hearing-format">送信用フォーマットをコピー</button></section><section class="client-submission"><div><span>クライアント提出通知</span><h3>eyebee 岡山黒石店：ヒアリング回答を提出しました</h3><p>提出日時：2025/05/21 14:20　/　サービス・ターゲット・強み・競合・画像素材・CV目的</p></div><button class="primary" data-action="confirm-hearing">提出内容を確認する</button></section><section class="hearing-summary"><h3>提出内容の要約</h3><div><b>ターゲット</b><span>30代女性／仕事帰りに通いたい／自然な目元を求める</span></div><div><b>CV目的</b><span>LINE登録 → 空き状況確認 → 予約完了</span></div></section></section>`;
  if(initialPhase===3)return `<section class="phase-panel"><header><span>PHASE 3</span><h2>ヒアリングデータからLPを制作</h2><p>提出された情報を4つに切り分け、制作担当が内容を整理したうえでLPを生成します。</p></header><div class="production-info-grid"><article><span>01</span><h3>基本情報</h3><p>店舗名、サービス、料金、所在地、営業時間、CV目的</p><b>整理済み</b></article><article><span>02</span><h3>デザイントンマナ</h3><p>色、写真の雰囲気、フォント、ブランドらしさ、避ける表現</p><b>整理済み</b></article><article><span>03</span><h3>コンセプト</h3><p>ターゲットの悩み、提供価値、差別化、LPで伝える約束</p><b>確認待ち</b></article><article><span>04</span><h3>原稿</h3><p>FV、サービス説明、料金、口コミ、FAQ、CTAの原稿案</p><b>作成中</b></article></div><section class="lp-generation-summary"><div><b>CodexによるLP生成</b><p>4つの情報をもとに、選択したテンプレートへコピー・構成・設定を反映します。</p></div><button class="primary" data-action="generate-initial-lp">整理した情報でLPを生成</button></section></section>`;
  if(initialPhase===4)return `<section class="phase-panel"><header><span>PHASE 4</span><h2>FOCを個別に画像生成</h2><p>LP全体とは別に、成果へ大きく影響するファーストビュー・オファー・CTAを個別に生成します。</p></header><div class="initial-foc-grid"><article><div class="initial-foc-preview fv"><b>EYEBEE</b><h3>疲れて見える<br>目元に、ヨサヨナ</h3></div><h3>ファーストビュー</h3><p>メインビジュアル・悩み訴求・初回価格</p><button class="secondary" data-action="generate-initial-assets">画像を生成</button></article><article><div class="initial-foc-preview offer"><b>初回限定</b><strong>5,500円</strong></div><h3>オファー</h3><p>特典・価格・期限が伝わる画像</p><button class="secondary" data-action="generate-initial-assets">画像を生成</button></article><article><div class="initial-foc-preview cta"><b>LINEで空き状況を確認</b></div><h3>CTA</h3><p>予約行動を促すボタン・補足画像</p><button class="secondary" data-action="generate-initial-assets">画像を生成</button></article></div><footer class="phase-footer"><small>各要素の生成結果は、LPの仮版へ反映されます。</small><button class="primary" data-action="issue-client-preview">確認用URLを発行する</button></footer></section>`;
  return `<section class="phase-panel"><header><span>PHASE 5</span><h2>クライアントにプレビューを送付</h2><p>制作したLPの確認用URLを発行し、クライアントの確認・承認後に公開します。</p></header><section class="preview-issue"><div><b>確認用プレビューURL</b><code>https://preview.example.com/eyebee/initial-lp</code><small>有効期限：2025/05/28 23:59　/　閲覧パスワード設定済み</small></div><button class="secondary">URLをコピー</button></section><section class="preview-checklist"><h3>送付前チェック</h3><label><input type="checkbox" checked> FOC（FV・オファー・CTA）の画像を反映済み</label><label><input type="checkbox" checked> GTM・CV設定を確認済み</label><label><input type="checkbox"> クライアント承認を取得</label></section><footer class="phase-footer"><small>承認後、公開URLへ反映し、ベースLPとして登録します。</small><button class="primary" data-action="send-initial-preview">クライアントへ確認依頼を送信</button></footer></section>`;
}
function initialProductionLegacyCompact(){const phases=['テンプレート複製','ヒアリングGPTs','LPを制作','FOC画像生成','クライアント確認'];return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">INITIAL LP PRODUCTION</div><h1>初期LP制作</h1><p class="page-sub">フェーズごとに必要な作業だけを進めます。</p></div><button class="secondary" onclick="go('initial-settings')">ベースLPを設定</button></div><nav class="initial-phase-nav">${phases.map((label,index)=>`<button class="${initialPhase===index+1?'active':''}" onclick="setInitialPhase(${index+1})"><i>${index+1}</i>${label}</button>`).join('')}</nav>${initialPhaseContent()}`}
function openInitialTemplatePreview(type){const recruit=type==='recruit';const modal=document.createElement('div');modal.className='initial-template-modal';modal.innerHTML=`<div class="initial-template-backdrop" onclick="closeInitialTemplatePreview()"></div><section class="initial-template-card"><button onclick="closeInitialTemplatePreview()">×</button><header><span>TEMPLATE PREVIEW</span><h3>${recruit?'求人LP':'サロン集客LP'}テンプレート</h3><p>テンプレートのスマホ表示イメージです。</p></header><div class="initial-template-phone ${recruit?'recruit':''}"><b>${recruit?'EYEBEE RECRUIT':'EYEBEE'}</b><div class="initial-template-photo"></div><h4>${recruit?'好きな仕事を、もっと自由に':'自然で上品な目元に、私らしさを。'}</h4><p>${recruit?'アイリスト募集中':'初回限定 5,500円'}</p><button>${recruit?'応募する':'LINEで予約する'}</button></div><footer><button class="secondary" onclick="closeInitialTemplatePreview()">閉じる</button><button class="primary" onclick="closeInitialTemplatePreview();setInitialPhase(2)">このテンプレートを選択</button></footer></section>`;document.body.appendChild(modal)}
function closeInitialTemplatePreview(){document.querySelector('.initial-template-modal')?.remove()}
function customerInfo(){return `<div class="client-page-label">個別クライアント画面　/　${selected.client}</div><div class="heading-row"><div><div class="eyebrow">CUSTOMER INFORMATION</div><h1>顧客情報</h1><p class="page-sub">ヒアリングGPTsから取得・整理した、LP制作と改善に利用する顧客情報です。</p></div><button class="secondary" onclick="go('initial-production')">初期LP制作を開く</button></div><section class="customer-source"><span>Hearing GPTs 提出データ</span><b>最終更新：2025/05/21 14:20</b></section><div class="customer-info-grid"><section><h3>基本情報</h3><dl><dt>店舗名</dt><dd>eyebee 岡山黒石店</dd><dt>サービス</dt><dd>まつげパーマ・眉毛スタイリング</dd><dt>CV目的</dt><dd>LINE登録 → 予約完了</dd></dl></section><section><h3>ターゲット・課題</h3><dl><dt>主なターゲット</dt><dd>30代女性／仕事帰り／自然な仕上がり志向</dd><dt>悩み</dt><dd>疲れて見える目元、メイク時短</dd><dt>競合との差</dt><dd>丁寧なカウンセリング・持続力</dd></dl></section><section><h3>デザイン・ブランド</h3><dl><dt>トンマナ</dt><dd>清潔感・やわらかい・上品</dd><dt>使用カラー</dt><dd>アイボリー／ブラウン／グリーン</dd><dt>避ける表現</dt><dd>過度な煽り・派手なカラー</dd></dl></section><section><h3>LP制作メモ</h3><dl><dt>コンセプト</dt><dd>忙しい毎日に、自信の持てる目元を</dd><dt>訴求</dt><dd>初回限定・短時間・自然な仕上がり</dd><dt>素材</dt><dd>店内写真／施術写真／口コミ</dd></dl></section></div>`}
